// Ported from antlr4-go v4.13.1 interval_set.go and the BitSet in utils.go.
//
// cel-go's parser is generated by ANTLR; its syntax error messages and error recovery come from the
// ANTLR runtime. This package ports the parts of that runtime the CEL grammar exercises so that error
// output matches cel-go byte for byte. The port keeps the Go runtime's quirks (e.g. in interval
// merging) on purpose.

/// Token type constants shared by the lexer and the ANTLR runtime port.
enum TokenType {
  static let invalid = 0
  static let epsilon = -2
  static let minUserTokenType = 1
  static let eof = -1
}

/// A half-open interval `[start, stop)` of token types.
struct Interval: Equatable {
  var start: Int
  var stop: Int

  func contains(_ item: Int) -> Bool {
    item >= start && item < stop
  }

  var length: Int { stop - start }
}

/// A set of integers stored as sorted intervals (antlr `IntervalSet`).
struct IntervalSet: Equatable {
  private(set) var intervals: [Interval]? = nil

  init() {}

  init(_ values: Int...) {
    for v in values {
      addOne(v)
    }
  }

  var first: Int {
    guard let intervals, !intervals.isEmpty else {
      return TokenType.invalid
    }
    return intervals[0].start
  }

  mutating func addOne(_ v: Int) {
    addInterval(Interval(start: v, stop: v + 1))
  }

  mutating func addRange(_ l: Int, _ h: Int) {
    addInterval(Interval(start: l, stop: h + 1))
  }

  mutating func addInterval(_ v: Interval) {
    guard var ivs = intervals else {
      intervals = [v]
      return
    }
    for k in ivs.indices {
      let interval = ivs[k]
      if v.stop < interval.start {
        ivs.insert(v, at: k)
        intervals = ivs
        return
      } else if v.stop == interval.start {
        ivs[k].start = v.start
        intervals = ivs
        return
      } else if v.start <= interval.stop {
        ivs[k] = Interval(start: min(interval.start, v.start), stop: max(interval.stop, v.stop))
        if k < ivs.count - 1 {
          let l = ivs[k]
          let r = ivs[k + 1]
          if l.stop >= r.stop {
            ivs.remove(at: k + 1)
          } else if l.stop >= r.start {
            ivs[k] = Interval(start: l.start, stop: r.stop)
            ivs.remove(at: k + 1)
          }
        }
        intervals = ivs
        return
      }
    }
    ivs.append(v)
    intervals = ivs
  }

  @discardableResult
  mutating func addSet(_ other: IntervalSet) -> IntervalSet {
    if let others = other.intervals {
      for i2 in others {
        addInterval(Interval(start: i2.start, stop: i2.stop))
      }
    }
    return self
  }

  func complement(_ start: Int, _ stop: Int) -> IntervalSet {
    var result = IntervalSet()
    result.addInterval(Interval(start: start, stop: stop + 1))
    if let ivs = intervals {
      for iv in ivs {
        result.removeRange(iv)
      }
    }
    return result
  }

  func contains(_ item: Int) -> Bool {
    guard let ivs = intervals else {
      return false
    }
    for iv in ivs where iv.contains(item) {
      return true
    }
    return false
  }

  var length: Int {
    (intervals ?? []).reduce(0) { $0 + $1.length }
  }

  mutating func removeRange(_ v: Interval) {
    if v.start == v.stop - 1 {
      removeOne(v.start)
      return
    }
    guard var ivs = intervals else {
      return
    }
    var k = 0
    var n = 0
    while n < ivs.count {
      defer { n += 1 }
      guard k >= 0, k < ivs.count else { break }
      let ni = ivs[k]
      if v.stop <= ni.start {
        intervals = ivs
        return
      } else if v.start > ni.start && v.stop < ni.stop {
        ivs[k] = Interval(start: ni.start, stop: v.start)
        let x = Interval(start: v.stop, stop: ni.stop)
        ivs.insert(x, at: k)
        intervals = ivs
        return
      } else if v.start <= ni.start && v.stop >= ni.stop {
        ivs.remove(at: k)
        k -= 1
      } else if v.start < ni.stop {
        ivs[k] = Interval(start: ni.start, stop: v.start)
      } else if v.stop < ni.stop {
        ivs[k] = Interval(start: v.stop, stop: ni.stop)
      }
      k += 1
    }
    intervals = ivs
  }

  mutating func removeOne(_ v: Int) {
    guard var ivs = intervals else {
      return
    }
    for k in ivs.indices {
      let ki = ivs[k]
      if v < ki.start {
        return
      } else if v == ki.start && v == ki.stop - 1 {
        ivs.remove(at: k)
        intervals = ivs
        return
      } else if v == ki.start {
        ivs[k] = Interval(start: ki.start + 1, stop: ki.stop)
        intervals = ivs
        return
      } else if v == ki.stop - 1 {
        ivs[k] = Interval(start: ki.start, stop: ki.stop - 1)
        intervals = ivs
        return
      } else if v < ki.stop - 1 {
        // The Go runtime splits into a copy and leaves the original interval in place.
        let x = Interval(start: ki.start, stop: v)
        ivs.insert(x, at: k)
        intervals = ivs
        return
      }
    }
  }

  /// Renders the set with token names, as antlr's `StringVerbose(literalNames, symbolicNames, false)`.
  func toTokenString(literalNames: [String], symbolicNames: [String]) -> String {
    guard let ivs = intervals else {
      return "{}"
    }
    var names: [String] = []
    for v in ivs {
      var j = v.start
      while j < v.stop {
        names.append(IntervalSet.elementName(literalNames, symbolicNames, j))
        j += 1
      }
    }
    if names.count > 1 {
      return "{" + names.joined(separator: ", ") + "}"
    }
    return names.first ?? ""
  }

  private static func elementName(_ literalNames: [String], _ symbolicNames: [String], _ a: Int)
    -> String
  {
    if a == TokenType.eof {
      return "<EOF>"
    } else if a == TokenType.epsilon {
      return "<EPSILON>"
    }
    if a >= 0 && a < literalNames.count && !literalNames[a].isEmpty {
      return literalNames[a]
    }
    if a >= 0 && a < symbolicNames.count {
      return symbolicNames[a]
    }
    return ""
  }
}

/// A small bit set of alternative numbers (antlr `BitSet`).
struct BitSet: Equatable, Hashable {
  private(set) var bits: UInt64 = 0

  init() {}

  mutating func add(_ value: Int) {
    precondition(value >= 0 && value < 64, "alternative number out of range")
    bits |= 1 << UInt64(value)
  }

  func contains(_ value: Int) -> Bool {
    value >= 0 && value < 64 && bits & (1 << UInt64(value)) != 0
  }

  mutating func or(_ other: BitSet) {
    bits |= other.bits
  }

  var length: Int { bits.nonzeroBitCount }

  var minValue: Int {
    bits == 0 ? 2_147_483_647 : bits.trailingZeroBitCount
  }
}
